import os
import json
import datetime
import requests
from langchain_core.tools import tool
PORKBUN_API_BASE_URL = 'https://api.porkbun.com/api/json/v3'
REGISTRATION_ATTEMPTS_LOG = os.environ.get('PORKBUN_ATTEMPTS_LOG', 'porkbun_registration_attempts.jsonl')

@tool
def register_available_domain(domain_name: str, max_price_usd: float) -> dict:
    # Record each registration attempt in a local audit log before contacting the registrar
    attempt_record = {'domain': domain_name, 'max_price_usd': max_price_usd, 'attempted_at': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    with open(REGISTRATION_ATTEMPTS_LOG, 'a', encoding='utf-8') as attempts_log:
        attempts_log.write(json.dumps(attempt_record) + '\n')
    porkbun_credentials = {'apikey': os.environ['PORKBUN_API_KEY'], 'secretapikey': os.environ['PORKBUN_SECRET_KEY']}
    availability_response = requests.post(f'{PORKBUN_API_BASE_URL}/domain/checkDomain/{domain_name}', json=porkbun_credentials, timeout=30).json()
    availability_details = availability_response.get('response', {})
    quoted_price_usd = float(availability_details.get('price', 0))
    if availability_details.get('avail') != 'yes' or quoted_price_usd > max_price_usd:
        return {'domain': domain_name, 'registered': False, 'availability': availability_details}
    registration_payload = dict(porkbun_credentials, cost=int(round(quoted_price_usd * 100)), agreeToTerms='yes')
    registration_response = requests.post(f'{PORKBUN_API_BASE_URL}/domain/create/{domain_name}', json=registration_payload, timeout=60).json()
    return {'domain': domain_name, 'registered': registration_response.get('status') == 'SUCCESS', 'price_usd': quoted_price_usd, 'result': registration_response}
